// Camel counting problem - dynamic programming with memoization
// Reads from stdin, writes to stdout

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
if (input.length < 2) {
    process.exit(0);
}
const n = input[0];
const t = input[1];

const MAX_Y = 4;

// Memoization map: key -> value
// key: `${pos},${prev},${dir},${peaks},${valleys}`
const memo = new Map();

function dfs(pos, prev, dir, peaks, valleys) {
    // pos: current position index (1-based). We have already assigned y at pos-1 = prev.
    // dir: -1 (down), 1 (up), 0 (undefined for first step)
    const key = `${pos},${prev},${dir},${peaks},${valleys}`;
    if (memo.has(key)) return memo.get(key);

    if (pos > n) {
        // Finished assigning all positions; check counts
        const res = (peaks === t && valleys === t - 1) ? 1n : 0n;
        memo.set(key, res);
        return res;
    }

    let total = 0n;
    for (let y = 1; y <= MAX_Y; y++) {
        if (y === prev) continue; // no horizontal segment

        let newDir = dir;
        let newPeaks = peaks;
        let newValleys = valleys;

        if (pos === 2) {
            // First step, direction is determined here
            newDir = (y > prev) ? 1 : -1;
        } else {
            // We have prev direction and now choose new y
            const curDir = (y > prev) ? 1 : -1;
            if (curDir !== dir) {
                // Direction change => either peak or valley at position pos-1
                if (dir === 1 && curDir === -1) {
                    // up then down => peak
                    newPeaks++;
                } else if (dir === -1 && curDir === 1) {
                    // down then up => valley
                    newValleys++;
                }
            }
            newDir = curDir;
        }

        // Prune if already impossible to reach required peaks/valleys
        // Remaining positions: n - pos
        // Each new internal point can contribute at most 1 peak or valley
        const remaining = n - pos;
        if (newPeaks > t || newValleys > t - 1) continue;
        if (newPeaks + remaining < t) continue;
        if (newValleys + remaining < t - 1) continue;

        total += dfs(pos + 1, y, newDir, newPeaks, newValleys);
    }

    memo.set(key, total);
    return total;
}

let answer = 0n;
for (let y1 = 1; y1 <= MAX_Y; y1++) {
    // Start at position 1 with y1
    answer += dfs(2, y1, 0, 0, 0);
}

