// Camel counting problem - Node.js solution

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
if (input.length < 2) process.exit(0);
const n = input[0];
const t = input[1];

// DP[pos][lastY][trend][peaks][valleys]
// trend: 0 = flat(start), 1 = up, 2 = down
// lastY: 1..4
// peaks, valleys: 0..t (cap at t)
const DP = [];
for (let pos = 0; pos <= n; pos++) {
    DP[pos] = [];
    for (let y = 0; y <= 4; y++) {
        DP[pos][y] = [];
        for (let tr = 0; tr < 3; tr++) {
            DP[pos][y][tr] = [];
            for (let p = 0; p <= t; p++) {
                DP[pos][y][tr][p] = new Array(t + 1).fill(0);
            }
        }
    }
}

// Initialize for position 1: choose any y1 in [1..4]
for (let y = 1; y <= 4; y++) {
    // pos=1, lastY=y, trend=0 (no direction yet), peaks=0, valleys=0
    DP[1][y][0][0][0] = 1;
}

// Transition
for (let pos = 1; pos < n; pos++) {
    for (let lastY = 1; lastY <= 4; lastY++) {
        for (let tr = 0; tr < 3; tr++) {
            for (let peaks = 0; peaks <= t; peaks++) {
                for (let valleys = 0; valleys <= t; valleys++) {
                    const curVal = DP[pos][lastY][tr][peaks][valleys];
                    if (!curVal) continue;

                    for (let ny = 1; ny <= 4; ny++) {
                        if (ny === lastY) continue; // no horizontal segment

                        let ntr;
                        if (ny > lastY) ntr = 1; // up
                        else ntr = 2; // down

                        let npeaks = peaks;
                        let nvalleys = valleys;

                        // From position >=2 we can detect peaks/valleys when trend changes
                        if (pos >= 2 && tr !== 0 && tr !== ntr) {
                            if (tr === 1 && ntr === 2) {
                                // up -> down : peak at pos
                                npeaks++;
                            } else if (tr === 2 && ntr === 1) {
                                // down -> up : valley at pos
                                nvalleys++;
                            }
                            if (npeaks > t || nvalleys > t - 1) continue;
                        }

                        DP[pos + 1][ny][ntr][npeaks][nvalleys] += curVal;
                    }
                }
            }
        }
    }
}

// Sum results at position n with exactly t peaks and t-1 valleys
let result = 0;
for (let lastY = 1; lastY <= 4; lastY++) {
    for (let tr = 0; tr < 3; tr++) {
        result += DP[n][lastY][tr][t][t - 1] || 0;
    }
}

